using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDay.API.Data;using RaceDay.API.DTOs;using RaceDay.API.Models;
namespace RaceDay.API.Controllers;
[ApiController,Route("api/results"),Authorize]
public class ResultsController(RaceDayDbContext db):ControllerBase {
 private int UserId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 /// <summary>Records or updates the result for an enrolment in an event owned by the organiser.</summary>
 [HttpPost,Authorize(Policy="OrganiserOnly")] public async Task<IActionResult> Record(ResultRequest r){var enrol=await db.Enrolments.Include(x=>x.Category).ThenInclude(c=>c.Event).FirstOrDefaultAsync(x=>x.EnrolmentID==r.EnrolmentID);if(enrol is null)return NotFound(new MessageResponse("Enrolment not found."));if(enrol.Category.Event.OrganiserID!=UserId)return Forbid();if(r.FinishPosition is <=0)return BadRequest(new MessageResponse("Finish position must be greater than zero."));if(r.FinishTime.HasValue && r.FinishTime.Value < TimeSpan.Zero)return BadRequest(new MessageResponse("Finish time cannot be negative."));if(r.ResultStatus is not("Finished" or "DNF" or "DNS" or "Disqualified"))return BadRequest(new MessageResponse("Invalid result status."));var result=await db.Results.SingleOrDefaultAsync(x=>x.EnrolmentID==r.EnrolmentID);if(result is null){result=new Result{EnrolmentID=r.EnrolmentID};db.Results.Add(result);}result.FinishPosition=r.FinishPosition;result.FinishTime=r.FinishTime;result.ResultStatus=r.ResultStatus;result.RecordedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(result);}
 /// <summary>Returns results belonging to the authenticated participant.</summary>
 [HttpGet("me"),Authorize(Policy="ParticipantOnly")] public async Task<IActionResult> Mine()=>Ok(await db.Results.Where(r=>r.Enrolment.ParticipantID==UserId).Include(r=>r.Enrolment).ThenInclude(e=>e.Category).ThenInclude(c=>c.Event).AsNoTracking().ToListAsync());
 /// <summary>Returns all results for an event owned by the authenticated organiser.</summary>
 [HttpGet("events/{eventId:int}"),Authorize(Policy="OrganiserOnly")] public async Task<IActionResult> ForEvent(int eventId){var e=await db.Events.FindAsync(eventId);if(e is null)return NotFound();if(e.OrganiserID!=UserId)return Forbid();return Ok(await db.Results.Where(r=>r.Enrolment.Category.EventID==eventId).Include(r=>r.Enrolment).ThenInclude(x=>x.Participant).Include(r=>r.Enrolment).ThenInclude(x=>x.Category).AsNoTracking().ToListAsync());}
 /// <summary>Returns a result to its participant or to the organiser who owns the event.</summary>
 [HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var r=await db.Results.Include(x=>x.Enrolment).ThenInclude(e=>e.Category).ThenInclude(c=>c.Event).FirstOrDefaultAsync(x=>x.ResultID==id);if(r is null)return NotFound();var role=User.FindFirstValue(ClaimTypes.Role);if(role=="Participant"&&r.Enrolment.ParticipantID!=UserId)return Forbid();if(role=="Organiser"&&r.Enrolment.Category.Event.OrganiserID!=UserId)return Forbid();return Ok(r);}
}
